import assert from 'node:assert/strict';
import { openNotes } from '../app/notes.mjs';
const values = new Map();
const storage = {
  getItem: key => values.get(key) ?? null,
  setItem: (key, value) => values.set(key, value)
};
const session = { id: 'session-42' };
openNotes(storage, [session]).write(session, 'Written after the update');
assert.equal(openNotes(storage, [session]).read(session), 'Written after the update');
console.log('New note survives reopening.');

