export function openNotes(storage, sessions) {
  const key = session => `notes-v2/${session.id}`;
  for (const session of sessions) {
    const previous = storage.getItem(`agenda-note:${session.id}`);
    if (storage.getItem(key(session)) === null && previous !== null) {
      storage.setItem(key(session), previous);
    }
  }
  return {
    read: session => storage.getItem(key(session)) ?? '',
    write: (session, text) => storage.setItem(key(session), text)
  };
}

